const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const box=e=>e?.getBoundingClientRect();
export function captureScene(s){if(!s)return {};return {deck:box(document.querySelector('.arena .pile:first-child .card')),top:box(document.querySelector('.arena .pile:last-child .card')),hand:Object.fromEntries([...document.querySelectorAll('[data-card]')].map(e=>[e.dataset.card,box(e)]))};}
function fly(html,from,to,delay=0){if(!from||!to||reduced())return;let e=document.createElement('div');e.className='flying-card';e.innerHTML=html;e.style.cssText=`left:${from.left}px;top:${from.top}px;width:${from.width}px;height:${from.height}px`;document.body.append(e);let dx=to.left+to.width/2-from.left-from.width/2,dy=to.top+to.height/2-from.top-from.height/2;
 e.animate([{transform:'translate(0,0) rotate(-8deg)',opacity:1},{transform:`translate(${dx*.5}px,${dy*.5-65}px) rotate(12deg) scale(1.12)`,offset:.5,opacity:1},{transform:`translate(${dx}px,${dy}px) rotate(0deg) scale(${to.width/from.width})`,opacity:.85}],{duration:650,delay,easing:'cubic-bezier(.2,.7,.25,1)',fill:'both'}).finished.finally(()=>e.remove());}
function sparks(rect,color){if(!rect||reduced())return;for(let i=0;i<16;i++){let e=document.createElement('i');e.className='spark';e.style.cssText=`left:${rect.left+rect.width/2}px;top:${rect.top+rect.height/2}px;background:var(--${color})`;document.body.append(e);let angle=i/16*Math.PI*2,r=60+Math.random()*90;e.animate([{transform:'translate(-50%,-50%) scale(1)',opacity:1},{transform:`translate(${Math.cos(angle)*r}px,${Math.sin(angle)*r}px) rotate(180deg) scale(0)`,opacity:0}],{duration:650,easing:'ease-out'}).finished.finally(()=>e.remove());}}
function shout(text,color){let e=document.createElement('div');e.className='action-shout';e.textContent=text;e.style.setProperty('--effect-color',`var(--${color})`);document.body.append(e);setTimeout(()=>e.remove(),1400);}
export function animateScene(before,after,scene){if(!before||after.status!=='playing')return;
 let top=document.querySelector('.arena .pile:last-child .card');
 if(before.top?.id!==after.top?.id){let actor=after.players.find(p=>p.count<(before.players.find(q=>q.id===p.id)?.count??0));let origin=scene.hand?.[after.top.id]||box(document.querySelector(`[data-player="${actor?.id}"]`));fly(top?.outerHTML,origin,box(top));sparks(box(top),after.color);let labels={skip:'TOUR SAUTÉ !',reverse:'DEMI-TOUR !','+2':'+2 · AÏE !','+4':'+4 · CHAOS !',wild:'NOUVELLE COULEUR !'};if(labels[after.top.v])shout(labels[after.top.v],after.color);
 }else {for(const p of after.players){let old=before.players.find(q=>q.id===p.id),n=p.count-(old?.count||p.count);if(n>0){let target=p.id===after.me?box(document.querySelector('.hand')):box(document.querySelector(`[data-player="${p.id}"]`));let html=document.querySelector('.arena .pile:first-child .card')?.outerHTML;for(let i=0;i<Math.min(n,6);i++)fly(html,scene.deck,target,i*90);}}}
 if(before.turn!==after.turn){let target=document.querySelector(`[data-player="${after.turn}"]`);if(target&&!reduced())target.animate([{transform:'scale(.96)',filter:'brightness(1.8)'},{transform:'scale(1)',filter:'brightness(1)'}],{duration:600,easing:'ease-out'});}
 if(before.feed?.[0]?.text!==after.feed?.[0]?.text&&after.feed?.[0]?.text.includes('crie NOVA'))shout('NOVA !','coral');
}
